const express = require('express');
const griddb = require('griddb-node-api');
const db = require('../db');

const app = express();
let gridStore;

griddb.StoreFactory.getInstance().getStore({
  host: process.env.GRIDDB_HOST,
  port: parseInt(process.env.GRIDDB_PORT || '10001'),
  clusterName: process.env.GRIDDB_CLUSTER,
  username: process.env.GRIDDB_USER,
  password: process.env.GRIDDB_PASSWORD
}).then(store => { gridStore = store; });

app.get('/api/meters/:meterId/series', async (req, res) => {
  const { meterId } = req.params;

  try {
    // Check that the meter is registered to the authenticated household
    const meterRecord = await db('smart_meters')
      .where({ meter_id: meterId, user_id: req.user.id })
      .first();
    if (!meterRecord) {
      return res.status(404).json({ error: 'Smart meter not found' });
    }

    // Open GridDB TimeSeries container after verifying ownership
    const container = await gridStore.getContainer(`meter_ts_${meterId}`);
    if (!container) {
      return res.status(404).json({ error: 'Smart meter time-series container not found' });
    }

    const query = container.query('SELECT * WHERE timestamp > TIMESTAMPADD(HOUR, NOW(), -24)');
    const rowSet = await query.fetch();
    const rows = [];
    while (rowSet.hasNext()) {
      rows.push(rowSet.next());
    }

    return res.json({ meterId, readings: rows });
  } catch (err) {
    return res.status(500).json({ error: 'GridDB query error' });
  }
});

module.exports = app;
